files.examples/01_identity.sql:
-- The modern way: an identity column (SQL standard, PostgreSQL 10+).
CREATE TABLE tickets (
  id    bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  title text NOT NULL
);

INSERT INTO tickets (title) VALUES ('Login fails'), ('Typo on pricing page')
RETURNING id, title;

-- Sequence values are never handed back: a rolled-back insert leaves a gap.
SAVEPOINT before_insert;
INSERT INTO tickets (title) VALUES ('Rolled back');
ROLLBACK TO SAVEPOINT before_insert;

INSERT INTO tickets (title) VALUES ('After the rollback')
RETURNING id, title;

-- It is still backed by a sequence, one the column owns and manages.
SELECT pg_get_serial_sequence('tickets', 'id')::regclass AS backing_sequence;

-- GENERATED ALWAYS refuses a hand-written id unless you say
-- OVERRIDING SYSTEM VALUE, so accidents can't happen quietly.
INSERT INTO tickets (id, title) VALUES (10, 'Imported by hand');

files.examples/02_serial.sql:
-- The legacy way: serial is shorthand for integer + a sequence + a DEFAULT.
CREATE TABLE old_tickets (
  id    serial PRIMARY KEY,
  title text NOT NULL
);

-- Nothing marks it as an identity: it is an ordinary integer column whose
-- default happens to call nextval().
SELECT data_type, column_default, is_identity
FROM information_schema.columns
WHERE table_schema = current_schema()
  AND table_name = 'old_tickets' AND column_name = 'id';

-- An import writes ids by hand, and serial accepts them without a word...
INSERT INTO old_tickets (id, title) VALUES (1, 'Imported'), (2, 'Imported too');

-- ...but the sequence never saw them, so the next default is 1 again.
INSERT INTO old_tickets (title) VALUES ('First new ticket');
